-- Fat Cat | loader.
--
--   loadstring(game:HttpGet("https://raw.githubusercontent.com/XzAngel19/FatCat-Deco/arena/292e8b51-fatcat-deco/src/FatCatHub.loader.lua"))()
--
-- Steps:
--   1. fetch src/FatCatHub.bundle.lua from the branch (raw GitHub),
--   2. compile it and report the exact line if the download is broken,
--   3. run it, which boots FatCatInit and builds the menu,
--   4. register getgenv().FatCatProjectUnload so a re-run cleans up first.
--
-- The bundle is the twenty project modules plus the window shell, generated by
-- tools/build_bundle.py. Editing a module under src/project/ only reaches the
-- executor after that script runs, which is why the generated file carries its
-- own "do not edit" header.
--
-- The menu never assumes it was loaded this way: pasting the bundle straight
-- into an executor works too, and so does loading src/FatCatHub.lua alone for
-- the window shell without the project tabs.
--
-- Diagnostics: set _G.FatCatHubVerbose = true to print every stage.
-- Branch override: set _G.FatCatHubBranch = "some/branch" before running.

-- Raw GitHub 404s until the branch contains the file, so the list below is
-- tried in order and the first response that looks like the bundle wins. That
-- makes the loader work before the work is merged into main, and stop caring
-- about the branch afterwards.
local BRANCHES = {
	"main",
	"arena/292e8b51-fatcat-deco",
	"arena/3f9165cb-fatcat-deco",
	"arena/4918f801-fatcat-deco",
}

local function branchList()
	if _G.FatCatHubBranch then
		return { _G.FatCatHubBranch }
	end
	return BRANCHES
end

-- Two URL shapes per branch: raw.githubusercontent, and github.com/.../raw,
-- which redirects to the same file. The second one exists because a branch name
-- with a slash in it can be mis-split by the raw host.
local function urlsFor(branch)
	return {
		("https://raw.githubusercontent.com/XzAngel19/FatCat-Deco/%s/src/FatCatHub.bundle.lua"):format(branch),
		("https://github.com/XzAngel19/FatCat-Deco/raw/%s/src/FatCatHub.bundle.lua"):format(branch),
	}
end

-- The executor environment, guarded for the same reason FatCatInit guards it:
-- a harness has no getgenv().
local ENV = (typeof(getgenv) == "function" and getgenv()) or _G

local function verbose(...)
	if _G.FatCatHubVerbose then
		print("[Fat Cat]", ...)
	end
end

local function report(message)
	warn("[Fat Cat] " .. message)
end

-- Character count without assuming `#` behaves the same on every executor's
-- string type; the size check below only needs "clearly longer than an error
-- page", not an exact byte count.
local function byteLength(text)
	local length = 0
	for _ in text:gmatch(".") do
		length += 1
	end
	return length
end

-- Reject anything that did not come back as the bundle: a 404 page, an empty
-- body, or an HTML error page served by a proxy.
local function looksLikeSource(body)
	if type(body) ~= "string" then
		return false, "the response was a " .. typeof(body) .. ", not a string"
	end
	local size = byteLength(body)
	if size < 2000 then
		return false, ("the response was only %d bytes - probably an error page"):format(size)
	end
	if body:find("^%s*<!DOCTYPE") or body:find("^%s*<html") then
		return false, "the server returned HTML instead of Lua"
	end
	-- The bundle declares these two markers in its header and its dispatch
	-- table; either one alone could appear in an error message.
	if not body:find("Fat Cat Project", 1, true) or not body:find("FatCatInit", 1, true) then
		return false, "the file did not look like the Fat Cat bundle"
	end
	return true
end

-- Walk the branches; inside one branch try the cached call first, then the
-- plain one, because a few executors only implement the single-argument form.
local function download()
	local lastError = "no branch was reachable"
	local tried = {}

	for _, branch in branchList() do
		tried[#tried + 1] = branch

		for _, url in urlsFor(branch) do
			local calls = {
				function()
					return game:HttpGet(url, true)
				end,
				function()
					return game:HttpGet(url)
				end,
			}

			for _, fetch in calls do
				local ok, body = pcall(fetch)
				if ok then
					local valid, why = looksLikeSource(body)
					if valid then
						verbose("loaded from branch", branch)
						return body, nil, branch
					end
					lastError = why
					verbose(url .. ": " .. why)
				else
					lastError = tostring(body)
					verbose(url .. ": HttpGet failed: " .. lastError)
				end
			end
		end
	end

	return nil, lastError, nil, tried
end

-- Compile, and on failure take two lines either side of the reported line so
-- the error is actionable instead of "something is wrong".
local function compile(source, chunkName)
	local chunk, compileError = loadstring(source, chunkName)
	if chunk then
		return chunk
	end

	local message = tostring(compileError)
	verbose("compile error:", message)

	local foundLine = message:match(":(%d+):")
	if foundLine then
		local number = tonumber(foundLine)
		-- The trailing newline and the non-greedy capture matter: a pattern
		-- that can match the empty string makes gmatch loop forever.
		local lines = {}
		for line in (source .. "\n"):gmatch("(.-)\n") do
			lines[#lines + 1] = line
		end
		for index = math.max(1, number - 2), math.min(#lines, number + 2) do
			warn(("%s %4d | %s"):format(index == number and ">" or " ", index, lines[index]))
		end
	end

	return nil, message
end

-- A previous run of either product (the bundle, or the shell on its own) has
-- to go before a second window is built.
local function teardownPrevious()
	local unload = ENV.FatCatProjectUnload
	if type(unload) == "function" then
		pcall(unload)
	elseif type(ENV.FatCatHubUnload) == "function" then
		pcall(ENV.FatCatHubUnload)
	end

	local core = _G.FatCatProject
	if type(core) == "table" and type(core.Destroy) == "function" then
		pcall(core.Destroy, core)
	end

	local hub = _G.FatCatHub
	if hub then
		pcall(function()
			hub:Destroy()
		end)
		_G.FatCatHub = nil
	end
end

-- Registered before the download, so an executor that dies mid-fetch still
-- leaves the user a working unload.
ENV.FatCatProjectUnload = function()
	local core = _G.FatCatProject
	if type(core) == "table" and type(core.Destroy) == "function" then
		pcall(core.Destroy, core)
	end
	local hub = _G.FatCatHub
	if hub then
		pcall(function()
			hub:Destroy()
		end)
		_G.FatCatHub = nil
	end
end

teardownPrevious()

local source, downloadError, usedBranch, tried = download()
if not source then
	report("could not download the bundle. Tried: " .. table.concat(tried or {}, ", "))
	report(tostring(downloadError))
	report("if the menu is in a branch that is not listed, run this first:")
	report('  _G.FatCatHubBranch = "your/branch"')
	return nil
end
verbose(("downloaded %d bytes from %s"):format(byteLength(source), usedBranch))

local chunk, compileError = compile(source, "FatCatProject")
if not chunk then
	report("the downloaded bundle did not compile: " .. tostring(compileError))
	return nil
end

local ran, result = pcall(chunk)
if not ran then
	report("the bundle failed at runtime: " .. tostring(result))
	return nil
end

-- The bundle returns the Init table; its boot result is on `result.booted`.
-- A shell-only download returns the Hub table instead, which is still a valid
-- outcome for that file, so both shapes are accepted here.
local Init = result
local booted = type(Init) == "table" and Init.booted or nil

if booted and not booted.ok then
	report(("boot failed at %s: %s"):format(tostring(booted.stage), tostring(booted.error)))
	report("the error card stays on screen; FatCatProjectUnload removes it")
	return nil
end

local Hub = _G.FatCatHub
if not Hub or not Hub._window then
	if Init and type(Init) == "table" and Init.__hub then
		Hub = Init.__hub
	end
	if not Hub or not Hub._window then
		report("the bundle ran but built no window.")
		return nil
	end
end

pcall(function()
	local summary = type(Init) == "table" and type(Init.report) == "function"
		and Init.report() or "Fat Cat ready"
	print(("[Fat Cat] ready - %s, press %s\n[Fat Cat] %s"):format(
		Hub._window.selected or "Home",
		tostring(Hub.menuKey or "RightShift"),
		summary
	))
end)

return Hub
